def parse_date(raw: str) -> date:
    """Turn one Borough ``value_date`` field, an ISO ``YYYY-MM-DD`` date, into a date."""
    try:
        return datetime.strptime(raw, "%Y-%m-%d").date()
    except ValueError as exc:
        raise LedgerParseError(f"Borough date {raw!r} is not YYYY-MM-DD") from exc


def parse_amount(raw: str) -> Decimal:
    """Turn one Borough ``amount`` field into dollars; see :func:`to_major_units`."""
    return to_major_units(raw)
